INSERT OR IGNORE INTO report_revisions(report_id,revision_no,title,explanation,trusted_assumptions,tool_version_id,environment,evidence_url,limitations,created_at) VALUES((SELECT id FROM reports WHERE create_key='staging-demo-reports-v1-arrayvec-Kani'),1,'arrayvec verification with Kani — initial scope','Synthetic staging report based on the original design examples.','Illustrative tool implementation, compiler and library models.','88ae942a-0e78-50ca-abac-580b96afe5d6','See each claim for the concrete types, bounds and features.','https://example.com/proofs-rs-demo/reports/1','Synthetic staging data. No proof was run.','2026-09-10T10:00:00.000Z');
INSERT OR IGNORE INTO claim_revisions(claim_id,report_id,report_revision,position,title,precondition,explanation,trusted_assumptions,evidence_url,limitations) VALUES('24724da4-486e-589f-a220-604669eb2038',(SELECT id FROM reports WHERE create_key='staging-demo-reports-v1-arrayvec-Kani'),1,0,'Pushing into a non-full ArrayVec does not panic','The vector is valid and len(v) < 8. The new element is a u8.'||char(10)||'∀ v : ArrayVec<u8, 8>, x : u8. valid(v) ∧ len(v) < 8 ⇒ ¬panics(v.push(x))','For the stated concrete type and capacity, push does not panic when at least one slot is available.','','https://example.com/proofs-rs-demo/17','T = u8; CAP = 8; x86_64; default features');
INSERT OR IGNORE INTO claim_revisions(claim_id,report_id,report_revision,position,title,precondition,explanation,trusted_assumptions,evidence_url,limitations) VALUES('2a70e186-633a-5680-b9d8-f8ae5bd2e0c3',(SELECT id FROM reports WHERE create_key='staging-demo-reports-v1-arrayvec-Kani'),1,1,'try_push returns an error at capacity','A valid ArrayVec<u8, 8>; every possible length from 0 through 8.'||char(10)||'∀ v : ArrayVec<u8, 8>, x : u8. valid(v) ⇒ ¬panics(v.try_push(x))','The full-capacity case is included. The result may be Err; success is not claimed.','','https://example.com/proofs-rs-demo/18','T = u8; CAP = 8; x86_64');
INSERT OR IGNORE INTO claim_revisions(claim_id,report_id,report_revision,position,title,precondition,explanation,trusted_assumptions,evidence_url,limitations) VALUES('fff8526c-8848-5260-9ef8-5cbf488e9b70',(SELECT id FROM reports WHERE create_key='staging-demo-reports-v1-arrayvec-Kani'),1,2,'No panic for u16 vectors with capacity 4','Valid vector with length less than 4.'||char(10)||'∀ v : ArrayVec<u16, 4>, x : u16. valid(v) ∧ len(v) < 4 ⇒ ¬panics(v.push(x))','A separate bounded claim with different element type and capacity.','','https://example.com/proofs-rs-demo/101','T = u16; CAP = 4');
INSERT OR IGNORE INTO claim_revisions(claim_id,report_id,report_revision,position,title,precondition,explanation,trusted_assumptions,evidence_url,limitations) VALUES('59820588-15cd-51a0-8632-65d3cfa8d7cd',(SELECT id FROM reports WHERE create_key='staging-demo-reports-v1-arrayvec-Kani'),1,3,'Push preserves the storage invariant for capacity 4','Valid vector and len(v) < 4; standard allocator model.'||char(10)||'valid(v) ∧ len(v) < 4 ⇒ defined(v.push(x)) ∧ valid(v′)','A separate bounded verification record.','','https://example.com/proofs-rs-demo/103','u8; CAP = 4; bounded model');
